#[derive(Debug,Clone,Copy,Serialize,Deserialize,PartialEq,Eq)]#[serde(rename_all="snake_case")]pub enum OperatorControlState{Running,Paused,Cancelling,Cancelled,EmergencyStopped,Sealed}
#[derive(Debug,Clone,Copy,Serialize,Deserialize,PartialEq,Eq)]#[serde(rename_all="snake_case")]pub enum IncidentClass{OperatorCancellation,EmergencyStop,InvalidCommand,ApprovalFailure}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]pub struct IncidentRecord{pub incident_id:String,pub class:IncidentClass,pub command_sequence:u64,pub reason_sha256:String,pub opened_at_milliseconds:u64,pub acknowledged_at_milliseconds:Option<u64>,pub incident_sha256:String}
impl IncidentRecord{fn new(class:IncidentClass,command_sequence:u64,reason_sha256:String,opened_at_milliseconds:u64)->Result<Self,AssuranceError>{let seed=hash_serializable(&(class,command_sequence,&reason_sha256,opened_at_milliseconds))?;let incident_id=format!("incident-{}",&seed[..24]);let incident_sha256=hash_serializable(&(&incident_id,class,command_sequence,&reason_sha256,opened_at_milliseconds,Option::<u64>::None))?;Ok(Self{incident_id,class,command_sequence,reason_sha256,opened_at_milliseconds,acknowledged_at_milliseconds:None,incident_sha256})}fn acknowledge(&mut self,at_milliseconds:u64)->Result<(),AssuranceError>{if self.acknowledged_at_milliseconds.is_some()||at_milliseconds<self.opened_at_milliseconds{return Err(AssuranceError::InvalidTransition("incident acknowledgement".into()));}self.acknowledged_at_milliseconds=Some(at_milliseconds);self.incident_sha256=hash_serializable(&(&self.incident_id,self.class,self.command_sequence,&self.reason_sha256,self.opened_at_milliseconds,self.acknowledged_at_milliseconds))?;Ok(())}pub fn is_open(&self)->bool{self.acknowledged_at_milliseconds.is_none()}}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]pub struct OperatorCommandReceipt{pub sequence:u64,pub command:OperatorCommand,pub prior_state:OperatorControlState,pub next_state:OperatorControlState,pub quorum_sha256:String,pub operator_ids:BTreeSet<String>,pub audit_tail_hash:String,pub receipt_sha256:String}
